-- One piece of work, many GC invitations, one estimate.
--
-- EXPAND ONLY. A new table, a nullable column and a defaulted column on
-- BidInvitation. Nothing is dropped or tightened, and `wonJobId` and
-- `projectName` keep working exactly as they did, so the build that is still
-- serving while this applies cannot be broken by it (CLAUDE.md: a drop and the
-- deploy that stops reading it do not land together).
--
-- Generated by `prisma migrate diff --from-schema-datamodel <HEAD> --to-schema-datamodel <this>`
-- (no database connection), then the backfill below was added by hand.

-- CreateEnum
CREATE TYPE "BidInvitationOrigin" AS ENUM ('INVITED', 'WE_REACHED_OUT');

-- AlterTable
ALTER TABLE "BidInvitation" ADD COLUMN     "bidProjectId" TEXT,
ADD COLUMN     "origin" "BidInvitationOrigin" NOT NULL DEFAULT 'INVITED';

-- CreateTable
