-- AddForeignKey
ALTER TABLE "BidProject" ADD CONSTRAINT "BidProject_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
