-- AddForeignKey
ALTER TABLE "BidInvitation" ADD CONSTRAINT "BidInvitation_bidProjectId_fkey" FOREIGN KEY ("bidProjectId") REFERENCES "BidProject"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Backfill: ONE PROJECT PER EXISTING INVITATION.
--
-- The migration never guesses which invitations are the same job — two GCs
-- name one building differently, and a wrong guess would point one estimate at
-- another job's costs. People merge them afterwards.
--
-- The project id is derived from the invitation id ('bpm' + id), so no
-- temporary column is needed to map one to the other and the statement is
-- deterministic. `wonJobId` is already UNIQUE, so copying it to the project's
-- UNIQUE `estimateJobId` cannot collide. Owner, architect and value come from
-- the invitation's pursuit when it has one (BidPursuit.bidInvitationId is
-- UNIQUE, so the join yields at most one row per invitation).
INSERT INTO "BidProject" (
    "id", "companyId", "name", "bidDueDate", "tradeScope", "estimateJobId",
    "owner", "architect", "estimatedValue", "createdAt", "updatedAt"
)
SELECT
    'bpm' || i."id", i."companyId", i."projectName", i."dueDate", i."tradeScope", i."wonJobId",
    p."owner", p."architect", p."estimatedValue", i."createdAt", CURRENT_TIMESTAMP
FROM "BidInvitation" i
LEFT JOIN "BidPursuit" p ON p."bidInvitationId" = i."id"
WHERE i."bidProjectId" IS NULL;

UPDATE "BidInvitation"
SET "bidProjectId" = 'bpm' || "id"
WHERE "bidProjectId" IS NULL;
